#!/usr/bin/env node

'use strict';

// Jetpack Compose Visual Verification Gate.
// Run as the last action after emulator screenshot-vs-design comparison.
// This script intentionally uses only Node built-ins.

var fs = require('fs');
var path = require('path');

function isDirectory(directory) {
  try {
    return fs.statSync(directory).isDirectory();
  } catch (_error) {
    return false;
  }
}

function isFile(file) {
  try {
    return fs.statSync(file).isFile();
  } catch (_error) {
    return false;
  }
}

function walk(start, maxDepth, include) {
  var results = [];

  function visit(current, depth) {
    var entries;
    try {
      entries = fs.readdirSync(current, { withFileTypes: true });
    } catch (_error) {
      return;
    }
    entries.sort(function (left, right) {
      return left.name.localeCompare(right.name);
    });
    for (var index = 0; index < entries.length; index += 1) {
      var entry = entries[index];
      var item = path.join(current, entry.name);
      if (include(item, entry)) {
        results.push(item);
      }
      if (
        entry.isDirectory() &&
        !entry.isSymbolicLink() &&
        depth < maxDepth &&
        entry.name !== '.git' &&
        entry.name !== 'node_modules' &&
        entry.name !== 'build'
      ) {
        visit(item, depth + 1);
      }
    }
  }

  visit(start, 0);
  return results;
}

function firstContextDirectory(projectDirectory) {
  var context = path.join(projectDirectory, '.locofy', 'context');
  return isDirectory(context) ? context : '';
}

function firstVisualReport(projectDirectory) {
  var report = path.join(
    projectDirectory,
    '.locofy',
    'agent',
    'memory',
    'visual-verification.md',
  );
  return isFile(report) ? report : '';
}

function parseArguments(args, projectDirectory) {
  var options = { screenshotMapping: '' };
  for (var index = 0; index < args.length; index += 1) {
    if (args[index] !== '--screenshot-mapping') {
      return { error: 'Unknown arg: ' + args[index] };
    }
    if (index + 1 >= args.length) {
      return { error: 'Missing value for --screenshot-mapping' };
    }
    options.screenshotMapping = path.resolve(projectDirectory, args[index + 1]);
    index += 1;
  }
  return { options: options };
}

function findScreenshotMappings(projectDirectory) {
  var agentDirectory = path.join(projectDirectory, '.locofy', 'agent');
  if (!isDirectory(agentDirectory)) {
    return [];
  }
  return walk(agentDirectory, 6, function (_item, entry) {
    return entry.isFile() && entry.name === 'screenshot-mapping.md';
  });
}

function imageReferences(content) {
  var matches =
    String(content || '').match(
      /(?:\\\\[^|<>"`\r\n]*?|[A-Za-z]:[\\/][^|<>"`\r\n]*?|(?:\.\.?[\\/]|\/)[^|<>"`\r\n]*?|[A-Za-z0-9_.:-]+(?:[\\/][^|<>"`\r\n]*?)?)\.(?:png|jpe?g|webp)\b/gi,
    ) || [];
  var seen = Object.create(null);
  return matches
    .map(function (item) {
      return item.trim();
    })
    .filter(function (item) {
      var key = item.replace(/\\/g, '/');
      if (seen[key]) {
        return false;
      }
      seen[key] = true;
      return true;
    });
}

function screenshotMappingContent(mapping) {
  var content = fs.readFileSync(mapping, 'utf8');
  var fileLines = content.split(/\r?\n/);
  var mappingLines = [];
  var navigationAssetsDepth = 0;
  for (var lineIndex = 0; lineIndex < fileLines.length; lineIndex += 1) {
    var heading = fileLines[lineIndex].match(/^\s*(#{1,6})\s+(.+?)\s*$/);
    if (heading && /\bNavigation Assets\b/i.test(heading[2])) {
      navigationAssetsDepth = heading[1].length;
      continue;
    }
    if (navigationAssetsDepth > 0) {
      if (heading && heading[1].length <= navigationAssetsDepth) {
        navigationAssetsDepth = 0;
      } else {
        continue;
      }
    }
    mappingLines.push(fileLines[lineIndex]);
  }
  return mappingLines.join('\n');
}

function mappedScreens(mapping) {
  return imageReferences(screenshotMappingContent(mapping));
}

function countMappedScreens(mapping) {
  return mappedScreens(mapping).length;
}

function identityTokens(value) {
  var aliases = {
    default: 'loaded',
    populated: 'loaded',
    success: 'loaded',
    successful: 'loaded',
  };
  var ignored = {
    capture: true,
    design: true,
    image: true,
    screen: true,
    screenshot: true,
    state: true,
    view: true,
  };
  return String(value || '')
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .map(function (token) {
      return aliases[token] || token;
    })
    .filter(function (token) {
      return token && !ignored[token] && !/^\d+$/.test(token);
    });
}

function countScreenshots(contextDirectory) {
  if (!isDirectory(contextDirectory)) {
    return 0;
  }
  try {
    return fs.readdirSync(contextDirectory, { withFileTypes: true }).filter(function (entry) {
      return entry.isFile() && entry.name.slice(-4) === '.png';
    }).length;
  } catch (_error) {
    return 0;
  }
}

function referencedPngs(report) {
  var matches =
    fs
      .readFileSync(report, 'utf8')
      .match(
        /(?:\\\\|[A-Za-z]:[\\/]|(?:\.\.?[\\/])|\/|[A-Za-z0-9_.-]+[\\/])[^|<>"`\r\n]*?\.png/g,
      ) || [];
  matches = matches.map(function (item) {
    return item.trim();
  });
  return matches.filter(function (item, index) {
    return matches.indexOf(item) === index;
  });
}

function resolveReportPath(reference, cwd) {
  return path.isAbsolute(reference) ? reference : path.resolve(cwd, reference);
}

function isInside(directory, file) {
  if (!directory) {
    return false;
  }
  var canonicalDirectory = path.resolve(directory);
  var canonicalFile = path.resolve(file);
  try {
    canonicalDirectory = fs.realpathSync(canonicalDirectory);
  } catch (_error) {
    return false;
  }
  try {
    canonicalFile = fs.realpathSync(canonicalFile);
  } catch (_error) {
    try {
      canonicalFile = path.join(
        fs.realpathSync(path.dirname(canonicalFile)),
        path.basename(canonicalFile),
      );
    } catch (_ignored) {
      // The later existence check reports missing evidence.
    }
  }
  var relative = path.relative(canonicalDirectory, canonicalFile);
  return relative !== '' && !relative.startsWith('..' + path.sep) && !path.isAbsolute(relative);
}

function main(args) {
  var projectDirectory = process.cwd();
  var parsed = parseArguments(args || [], projectDirectory);
  if (parsed.error) {
    console.log('FAIL:VISUAL_ARGUMENTS=' + parsed.error);
    console.log('VISUAL_RESULT:FAIL count=1');
    return 1;
  }

  var mapping = parsed.options.screenshotMapping;
  var mappingError = '';
  if (mapping) {
    if (!isFile(mapping)) {
      mappingError = 'VISUAL_MAPPING_MISSING=' + mapping;
    }
  } else {
    var mappings = findScreenshotMappings(projectDirectory);
    if (mappings.length === 1) {
      mapping = mappings[0];
    } else if (mappings.length === 0) {
      mappingError =
        'VISUAL_MAPPING_MISSING pass --screenshot-mapping <incoming>/.locofy/memory/screenshot-mapping.md';
    } else {
      mappingError =
        'VISUAL_MAPPING_AMBIGUOUS count=' +
        mappings.length +
        ' pass --screenshot-mapping for the current merge';
    }
  }

  var contextDirectory = firstContextDirectory(projectDirectory);
  var report = firstVisualReport(projectDirectory);
  var mappingScreens = mapping && isFile(mapping) ? mappedScreens(mapping) : [];
  var mappingText = mapping && isFile(mapping) ? screenshotMappingContent(mapping) : '';
  var screens = mappingScreens.length;
  var mappingModifiedAt = mapping && isFile(mapping) ? fs.statSync(mapping).mtimeMs : 0;
  var references = report ? referencedPngs(report) : [];
  var reportContent = report ? fs.readFileSync(report, 'utf8') : '';
  var reportImages = report ? imageReferences(reportContent) : [];
  var reportImageKeys = Object.create(null);
  for (var reportImageIndex = 0; reportImageIndex < reportImages.length; reportImageIndex += 1) {
    var reportImageKey = reportImages[reportImageIndex].replace(/\\/g, '/');
    if (process.platform === 'win32') {
      reportImageKey = reportImageKey.toLowerCase();
    }
    reportImageKeys[reportImageKey] = true;
  }
  var matchedMappingScreens = mappingScreens.filter(function (mappingScreen) {
    var mappingScreenKey = mappingScreen.replace(/\\/g, '/');
    if (process.platform === 'win32') {
      mappingScreenKey = mappingScreenKey.toLowerCase();
    }
    return reportImageKeys[mappingScreenKey];
  });
  var capturedReferences = [];
  var currentCapturedReferences = [];
  var seenCapturePaths = Object.create(null);
  for (var referenceIndex = 0; referenceIndex < references.length; referenceIndex += 1) {
    var resolvedReference = resolveReportPath(references[referenceIndex], projectDirectory);
    if (!isInside(contextDirectory, resolvedReference)) {
      continue;
    }
    var canonicalReference = path.resolve(resolvedReference);
    try {
      canonicalReference = fs.realpathSync(canonicalReference);
    } catch (_error) {
      // Missing captures are checked below using their resolved path.
    }
    var captureKey =
      process.platform === 'win32' ? canonicalReference.toLowerCase() : canonicalReference;
    if (seenCapturePaths[captureKey]) {
      continue;
    }
    seenCapturePaths[captureKey] = true;
    capturedReferences.push({
      path: canonicalReference,
      reference: references[referenceIndex],
    });
    if (
      isFile(canonicalReference) &&
      fs.statSync(canonicalReference).mtimeMs >= mappingModifiedAt
    ) {
      currentCapturedReferences.push(canonicalReference);
    }
  }
  var screenshots = currentCapturedReferences.length;
  var associatedMappingRows = matchedMappingScreens.length;
  if (
    associatedMappingRows === 0 &&
    currentCapturedReferences.length >= screens &&
    screens > 0
  ) {
    var mappingIdentityTokens = Object.create(null);
    identityTokens(mappingText).forEach(function (token) {
      mappingIdentityTokens[token] = true;
    });
    var capturesMatchMapping = currentCapturedReferences.every(function (capture) {
      var captureTokens = identityTokens(path.basename(capture, path.extname(capture)));
      return (
        captureTokens.length > 0 &&
        captureTokens.every(function (token) {
          return mappingIdentityTokens[token];
        })
      );
    });
    if (capturesMatchMapping) {
      associatedMappingRows = screens;
    }
  }
  var failCount = 0;

  function pass(name) {
    console.log('OK:' + name);
  }

  function fail(detail) {
    console.log('FAIL:' + detail);
    failCount += 1;
  }

  console.log(
    'SCREENS=' +
      screens +
      ' CAPTURED=' +
      screenshots +
      ' CTX=' +
      (contextDirectory || 'none') +
      ' REPORT=' +
      (report || 'none') +
      ' MAPPING=' +
      (mapping || 'none'),
  );

  if (mappingError) {
    fail(mappingError);
  } else if (screens === 0) {
    fail('VISUAL_MAPPING_EMPTY no screenshot rows found in ' + mapping);
  } else if (screenshots < screens) {
    fail('VISUAL_SCREENSHOTS_MISSING captured=' + screenshots + ' screens=' + screens);
  } else {
    pass('VISUAL_SCREENSHOTS');
  }

  if (!report) {
    fail('VISUAL_REPORT_MISSING (write .locofy/agent/memory/visual-verification.md)');
  } else {
    if (fs.statSync(report).mtimeMs < mappingModifiedAt) {
      fail('VISUAL_REPORT_STALE report predates current screenshot mapping');
    } else {
      pass('VISUAL_REPORT');
    }
    if (associatedMappingRows < screens) {
      fail(
        'VISUAL_MAPPING_ROWS_MISSING mappedRefs=' +
          associatedMappingRows +
          ' screens=' +
          screens,
      );
    }
    if (currentCapturedReferences.length < screens) {
      fail(
        'VISUAL_REPORT_ROWS_MISSING capturedRefs=' +
          currentCapturedReferences.length +
          ' screens=' +
          screens,
      );
    }
    for (var index = 0; index < capturedReferences.length; index += 1) {
      if (!isFile(capturedReferences[index].path)) {
        fail('VISUAL_PNG_MISSING=' + capturedReferences[index].reference);
      }
    }

    if (reportContent.indexOf('DEVICE:') === -1) {
      fail('VISUAL_DEVICE_MISSING record DEVICE:<model>');
    }
    var statusBarPasses = (reportContent.match(/STATUS_BAR:VISIBLE/g) || []).length;
    var cameraCutoutPasses = (reportContent.match(/CAMERA_CUTOUT:VISIBLE/g) || []).length;
    var safeAreaPasses = (reportContent.match(/SAFE_AREA:PASS/g) || []).length;
    if (statusBarPasses < screens) {
      fail(
        'STATUS_BAR_EVIDENCE_MISSING visible=' + statusBarPasses + ' screens=' + screens,
      );
    } else {
      pass('STATUS_BAR_VISIBLE');
    }
    if (cameraCutoutPasses < screens) {
      fail(
        'CAMERA_CUTOUT_EVIDENCE_MISSING visible=' +
          cameraCutoutPasses +
          ' screens=' +
          screens,
      );
    } else {
      pass('CAMERA_CUTOUT_VISIBLE');
    }
    if (safeAreaPasses < screens) {
      fail('SAFE_AREA_EVIDENCE_MISSING passed=' + safeAreaPasses + ' screens=' + screens);
    } else {
      pass('SAFE_AREA');
    }
    if (
      /SAFE_AREA:FAIL|(?:STATUS_BAR|CAMERA_CUTOUT):(?:HIDDEN|CROPPED|FAIL)/.test(
        reportContent,
      )
    ) {
      fail('SAFE_AREA_OVERLAP_OR_SYSTEM_UI_HIDDEN');
    }
  }

  if (failCount === 0) {
    console.log('VISUAL_RESULT:ALL_PASS');
    return 0;
  }
  console.log('VISUAL_RESULT:FAIL count=' + failCount);
  return 1;
}

module.exports = {
  countMappedScreens: countMappedScreens,
  countScreenshots: countScreenshots,
  findScreenshotMappings: findScreenshotMappings,
  firstContextDirectory: firstContextDirectory,
  firstVisualReport: firstVisualReport,
  isInside: isInside,
  identityTokens: identityTokens,
  mappedScreens: mappedScreens,
  parseArguments: parseArguments,
  referencedPngs: referencedPngs,
  resolveReportPath: resolveReportPath,
};

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}
